import { prisma } from '@/lib/prisma';
import { Suspense } from 'react';

// 1. Dedicated data fetching function
async function getRecentOrders() {
  return await prisma.order.findMany({
    where: { status: 'COMPLETED' },
    include: { customer: { select: { name: true, email: true } } },
    orderBy: { createdAt: 'desc' },
    take: 5,
  });
}

// 2. Server Component
export default async function DashboardPage() {
  const orders = await getRecentOrders();

  return (
    <main className="p-8 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">Recent Orders</h1>
      <div className="space-y-4">
        {orders.map((order) => (
          <div key={order.id} className="p-4 border rounded shadow-sm flex justify-between">
            <div>
              <p className="font-medium">{order.customer.name}</p>
              <p className="text-sm text-gray-500">{order.customer.email}</p>
            </div>
            <span className="font-semibold">${order.totalAmount.toString()}</span>
          </div>
        ))}
      </div>
    </main>
  );
}
